/* ===========================================================================
 * dpCal.c：内核 DP 计算实现。
 *
 * 本文件由 Adventure.c 拆分而来，只承载两个 DP 入口：
 *   - dpMaxAverage：从当前状态出发的剩余期望最大得分
 *   - dpGoalProb ：从当前状态出发、最终总分达到目标 T 的概率
 *
 * 依赖的规则常量 / 纯工具函数（judgeGroup、question_db_for_type、
 * totalQs、needPick、successScore、failScore、maxRemainingScore、
 * convert_group_mask、mask_count、encode_flat_key、prune_options、
 * OPT_PER_QUESTION、StateVec 等）仍留在 Adventure.c，
 * 通过 Adventure.h 暴露——见 dpCal.h 顶部说明。
 * =========================================================================== */
#define _CRT_SECURE_NO_WARNINGS
#include "dpCal.h"
#include <string.h>   /* memset */

/* ===================== DP：期望最优分 ===================== */
double dpMaxAverage(MemoHash *memo, uint16_t group_mask, const Attrs raw_attr,
                    int done_cnt)
{
    if (raw_attr.health <= 0 || done_cnt == 10)
        return 0;

    uint64_t fkey = encode_flat_key(group_mask, raw_attr, (uint8_t)done_cnt, NO_REMAIN_AIM_SCORE);
    HashEntry *entry = memo_hash_lookup(memo, fkey);
    if (entry != NULL) return entry->val;

    int type = judgeGroup(done_cnt);
    int totalq = totalQs[type];
    int needpick = needPick[type];
    const Question *question_db = question_db_for_type(type);
    double sum_best = 0;
    int remaining = totalq - mask_count(group_mask);

    for (int q_idx = 0; q_idx < totalq; q_idx++) {
        double best = 0;
        uint16_t q_bit = convert_group_mask(q_idx);
        if ((group_mask & q_bit) != 0) continue;

        const Question *q = &question_db[q_idx];
        StateVec vecs[4];
        bool keep[4];
        prune_options(q, raw_attr, done_cnt, vecs, keep);

        for (int opt = 0; opt < (int)OPT_PER_QUESTION; opt++) {
            if (!keep[opt]) continue;
            const StateVec *v = &vecs[opt];
            Attrs new_attr = {
                .health = (int8_t)v->h,
                .power = (int8_t)v->p,
                .wisdom = (int8_t)v->w,
                .charm = (int8_t)v->c,
                .luck = (int8_t)v->l,
                .agility = (int8_t)v->a,
            };
            int delta_score = v->sc ? successScore[type] : failScore[type];
            int new_done = done_cnt + 1;
            uint16_t new_mask = (mask_count(group_mask) + 1 == needpick) ? 0 : (group_mask | q_bit);

            double sub_ret = dpMaxAverage(memo, new_mask, new_attr, new_done);
            if (delta_score + sub_ret > best)
                best = delta_score + sub_ret;
        }
        sum_best += best;
    }

    double result = sum_best / remaining;
    memo_hash_put(memo, fkey, result, FALSE);
    return result;
}



#define MIN_ROLES   1
#define MAX_ROLES   7
#define MAX_ROUND 6  // game_round 第x局: (0-6)
#define MAX_LOSE620    80   /* 总可丢分上限 */
#define MAX_LOSE480   220

static const int cumScore[11] = { 0, 6, 12, 18, 27, 36, 45, 57, 69, 81, 100 };
/* ===================== DP：达到目标 T 的最优概率 ===================== */
/* 子问题 (mask, attr, done, r) 只依赖"还差 r 分"，与顶层目标 T 无关，
 * 因此同一张 memo 可跨 T 复用，缓存文件无需按 T 拆分。 */
double dpGoalProb(MemoHash *memo, uint16_t group_mask, const Attrs role_attr,
                  int done_cnt, int r)
{
    int able_lost = 100 - r - cumScore[done_cnt];
    return dpGlobalProMax(memo, group_mask, role_attr, done_cnt, able_lost,
                          MAX_ROUND, NULL, 0);
}

